import { useState, useEffect } from 'react'
import { getDeviceList, DeviceManagementTypes } from '@/apis/admin/device-management'
import { getSysCommunityList } from '@/apis/admin/system-config'
import { SystemConfigTypes } from '@/apis/admin/system-config/types'
import AreaCascader from '@/components/AreaCascader'
import { Select, Checkbox, Tag, Card, Row, Col, Pagination } from 'antd'
import { ResultEnum } from '@/utils/enums/httpEnum'

interface DeviceSelectorProps {
  /** 选中的设备对象数组 */
  value?: DeviceManagementTypes.DeviceListDto[]
  /** 选中设备变化时的回调 */
  onChange?: (devices: DeviceManagementTypes.DeviceListDto[]) => void
  /** 是否支持多选，默认为 true */
  multiple?: boolean
}

const PAGE_SIZE = 50

const DeviceSelector: React.FC<DeviceSelectorProps> = ({
  value = [],
  onChange,
  multiple = true
}) => {
  const [deviceList, setDeviceList] = useState<DeviceManagementTypes.DeviceListDto[]>([])
  const [filteredDeviceList, setFilteredDeviceList] = useState<DeviceManagementTypes.DeviceListDto[]>([])
  const [communityList, setCommunityList] = useState<SystemConfigTypes.SysCommunityListDto[]>([])
  const [filterAreaIds, setFilterAreaIds] = useState<string[]>([])
  const [filterCommunity, setFilterCommunity] = useState<number | undefined>()
  const [currentPage, setCurrentPage] = useState(1)
  const [loading, setLoading] = useState(false)

  // 加载设备列表
  const loadDeviceList = async () => {
    try {
      setLoading(true)
      const res = await getDeviceList({ pageSize: 50 })
      if (res.code === ResultEnum.SUCCESS && res.data?.list) {
        setDeviceList(res.data.list)
        setFilteredDeviceList(res.data.list)
        setCurrentPage(1)
      }
    } catch (e) {
      console.error('加载设备列表失败:', e)
    } finally {
      setLoading(false)
    }
  }

  // 加载小区列表（根据省市区筛选）
  const loadCommunityList = async (provinceId?: number, cityId?: number, areaId?: number) => {
    try {
      const res = await getSysCommunityList({ provinceId, cityId, areaId })
      if (res.code === ResultEnum.SUCCESS && res.data?.list) {
        setCommunityList(res.data.list)
      }
    } catch (e) {
      console.error('加载小区列表失败:', e)
    }
  }

  // 组件挂载时加载数据
  useEffect(() => {
    loadDeviceList()
    loadCommunityList()
  }, [])

  // 获取选中的设备ID数组
  const selectedDeviceIds = value.map(d => d.id)

  // 获取小区选项
  const getCommunityOptions = () => {
    return communityList.map(item => ({
      label: item.communityName,
      value: item.id
    }))
  }

  // 筛选设备
  const filterDevices = (areaIds?: string[], communityId?: number) => {
    let filtered = deviceList

    // 根据省市区ID筛选
    if (areaIds && areaIds.length > 0) {
      // areaIds 格式: [provinceId, cityId, areaId]
      const [provinceId, cityId, areaId] = areaIds

      if (provinceId) {
        filtered = filtered.filter(d => d.provinceId.toString() === provinceId)
      }
      if (cityId) {
        filtered = filtered.filter(d => d.cityId.toString() === cityId)
      }
      if (areaId) {
        filtered = filtered.filter(d => d.areaId.toString() === areaId)
      }
    }

    // 根据小区ID筛选
    if (communityId) {
      filtered = filtered.filter(d => d.communityId === communityId)
    }

    setFilteredDeviceList(filtered)
    setCurrentPage(1)
  }

  // 处理地区筛选变化
  const handleAreaChange = (result: { labels: string[]; values: string[] }) => {
    setFilterAreaIds(result.values)
    // 根据省市区加载对应小区
    const ids = result.values || []
    const provinceId = ids[0] ? Number(ids[0]) : undefined
    const cityId = ids[1] ? Number(ids[1]) : undefined
    const areaId = ids[2] ? Number(ids[2]) : undefined
    loadCommunityList(provinceId, cityId, areaId)
    // 重置小区选择
    setFilterCommunity(undefined)
    filterDevices(result.values, undefined)
  }

  // 处理小区筛选变化
  const handleCommunityChange = (value?: number) => {
    setFilterCommunity(value)
    filterDevices(filterAreaIds, value)
  }

  // 处理设备选择
  const handleDeviceSelect = (deviceId: number, checked: boolean) => {
    const device = deviceList.find(d => d.id === deviceId)
    if (!device) {
      return
    }

    if (checked) {
      if (multiple) {
        // 多选模式
        const newValue = [...value, device]
        onChange?.(newValue)
      } else {
        // 单选模式
        onChange?.([device])
      }
    } else {
      // 取消选择
      const newValue = value.filter(d => d.id !== deviceId)
      onChange?.(newValue)
    }
  }

  // 处理分页变化
  const handlePageChange = (page: number) => {
    setCurrentPage(page)
  }

  // 获取当前页的数据
  const getCurrentPageData = () => {
    const start = (currentPage - 1) * PAGE_SIZE
    const end = start + PAGE_SIZE
    return filteredDeviceList.slice(start, end)
  }

  // 计算总页数
  const totalPages = Math.ceil(filteredDeviceList.length / PAGE_SIZE)

  return (
    <Card size="small" style={{ background: '#F8FAFC' }} bodyStyle={{ padding: 12 }}>
      {/* 省市区及小区筛选 */}
      <Row gutter={12} style={{ marginBottom: 12 }}>
        <Col span={16}>
          <AreaCascader
            placeholder="选择省市区"
            asyncMode={true}
            onChange={handleAreaChange}
            styles={{ width: '100%' }}
          />
        </Col>
        <Col span={8}>
          <Select
            placeholder={filterAreaIds.length > 0 ? '选择小区' : '请先选择省市区'}
            value={filterCommunity}
            onChange={handleCommunityChange}
            style={{ width: '100%' }}
            allowClear
            showSearch
            disabled={filterAreaIds.length === 0}
            filterOption={(input, option) =>
              String(option?.children || '').toLowerCase().includes(input.toLowerCase())
            }
          >
            {getCommunityOptions().map(opt => (
              <Select.Option key={opt.value} value={opt.value}>
                {opt.label}
              </Select.Option>
            ))}
          </Select>
        </Col>
      </Row>

      <div style={{ marginBottom: 8, fontSize: 12, color: '#64748B' }}>
        共 <b>{filteredDeviceList.length}</b> 台设备
        {value.length > 0 && (
          <span style={{ marginLeft: 16, color: '#2563EB' }}>
            已选择 <b>{value.length}</b> 台
          </span>
        )}
      </div>

      <div
        style={{
          minHeight: 200,
          maxHeight: 400,
          overflow: 'auto',
          padding: 8,
          background: '#fff',
          borderRadius: 4,
          border: '1px solid #E2E8F0'
        }}
      >
        {filteredDeviceList.length === 0 ? (
          <div style={{ textAlign: 'center', color: '#999', padding: 20 }}>
            {deviceList.length === 0 ? '暂无设备数据' : '请先选择地区筛选设备'}
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {getCurrentPageData().map(device => {
              const isSelected = selectedDeviceIds.includes(device.id)
              return (
                <label
                  key={device.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 8,
                    padding: '8px 12px',
                    background: isSelected ? '#EFF6FF' : '#fff',
                    border: `1px solid ${isSelected ? '#2563EB' : '#E2E8F0'}`,
                    borderRadius: 6,
                    cursor: 'pointer'
                  }}
                >
                  <Checkbox
                    checked={isSelected}
                    onChange={e => handleDeviceSelect(device.id, e.target.checked)}
                  />
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: 13, fontWeight: 500 }}>
                      {device.deviceName || device.imei}
                      <span style={{ color: '#64748B', fontWeight: 400, marginLeft: 8 }}>
                        ({device.imei})
                      </span>
                    </div>
                    <div style={{ fontSize: 12, color: '#64748B' }}>
                      省份{device.provinceId} 城市{device.cityId} 区县{device.areaId}
                      {device.communityId && ` · 小区${device.communityId}`}
                    </div>
                  </div>
                  {isSelected && <Tag color="blue">已选</Tag>}
                </label>
              )
            })}
          </div>
        )}
      </div>

      {/* 分页器 */}
      {filteredDeviceList.length > PAGE_SIZE && (
        <div style={{ marginTop: 12, display: 'flex', justifyContent: 'flex-end' }}>
          <Pagination
            current={currentPage}
            pageSize={PAGE_SIZE}
            total={filteredDeviceList.length}
            onChange={handlePageChange}
            showSizeChanger={false}
            showQuickJumper
            showTotal={(total) => `共 ${total} 条`}
            size="small"
          />
        </div>
      )}

      {value.length > 0 && (
        <div style={{ marginTop: 12, paddingTop: 12, borderTop: '1px solid #E2E8F0' }}>
          <span style={{ fontSize: 13, color: '#64748B' }}>已选设备：</span>
          <div style={{ marginTop: 8, display: 'flex', flexWrap: 'wrap', gap: 8 }}>
            {value.map(device => (
              <Tag key={device.id} color="blue">
                {device.deviceName || device.imei}
              </Tag>
            ))}
          </div>
        </div>
      )}
    </Card>
  )
}

export default DeviceSelector
